export type Recipient = {
  name: string;
  postalAddress: string;
};

export type ProviderRequest = {
  shipmentId: string;
  routeCode: string;
  parcelGrams: number;
  recipient: Recipient;
  idempotencyKey: string;
};

type Provider = "atlas" | "beacon";
type RefusalReason = "unsupported_route" | "unsupported_parcel";
type AbortClassification =
  | "unknown_failure"
  | "invalid_provider_response"
  | "repository_failure";

type CarrierRejection = Readonly<{
  provider: Provider;
  reason: RefusalReason;
}>;

export type ShippingDependencies = {
  repository: {
    get: (shipmentId: string) => Promise<unknown>;
    save: (shipmentId: string, record: unknown) => Promise<void>;
  };
  atlas: {
    book: (request: ProviderRequest) => Promise<unknown>;
  };
  beacon: {
    reserve: (request: ProviderRequest) => Promise<unknown>;
  };
  logger: {
    info: (event: Record<string, unknown>) => void;
  };
};

type ShipmentFields = Readonly<{
  schemaVersion: 1;
  id: string;
  routeCode: string;
  parcelGrams: number;
}>;

type QueuedShipment = ShipmentFields & Readonly<{
  state: "queued";
}>;

type DispatchedShipment = ShipmentFields & Readonly<{
  state: "dispatched";
  provider: Provider;
  bookingId: string;
  dispatchedAtMs: number;
}>;

type DeferredShipment = ShipmentFields & Readonly<{
  state: "deferred";
  nextProvider: Provider;
  retryAtMs: number;
  rejections: readonly CarrierRejection[];
}>;

type UnavailableShipment = ShipmentFields & Readonly<{
  state: "unavailable";
  rejections: readonly CarrierRejection[];
}>;

type StoredShipment =
  | QueuedShipment
  | DispatchedShipment
  | DeferredShipment
  | UnavailableShipment;
export type PublicShipment =
  | Omit<QueuedShipment, "schemaVersion">
  | Omit<DispatchedShipment, "schemaVersion">
  | Omit<DeferredShipment, "schemaVersion">
  | Omit<UnavailableShipment, "schemaVersion">;

type ErrorBody =
  | { code: "invalid_command" | "not_found" }
  | AbortBody;

type AbortBody = {
  code: "dispatch_aborted";
  shipmentId: string;
  failedAt: Provider | "repository";
  classification: AbortClassification;
  rejections: CarrierRejection[];
};

export type ServiceResponse = {
  status: number;
  body: PublicShipment | ErrorBody;
};

type Command =
  | { op: "get"; shipmentId: string }
  | { op: "dispatch"; shipmentId: string; nowMs: number; recipient: Recipient };

type CarrierResult =
  | Readonly<{ kind: "confirmed"; provider: Provider; bookingId: string }>
  | Readonly<{ kind: "refused"; rejection: CarrierRejection }>
  | Readonly<{ kind: "throttled"; provider: Provider; retryAtMs: number }>
  | Readonly<{
      kind: "aborted";
      failedAt: Provider;
      classification: "unknown_failure" | "invalid_provider_response";
    }>;

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function parseCommand(value: unknown): Command | undefined {
  if (!isObject(value) || typeof value.shipmentId !== "string" || value.shipmentId.length === 0) {
    return undefined;
  }
  if (value.op === "get") {
    return { op: "get", shipmentId: value.shipmentId };
  }
  if (
    value.op !== "dispatch" ||
    typeof value.nowMs !== "number" ||
    !Number.isSafeInteger(value.nowMs) ||
    value.nowMs < 0 ||
    !isObject(value.recipient) ||
    typeof value.recipient.name !== "string" ||
    value.recipient.name.trim().length === 0 ||
    typeof value.recipient.postalAddress !== "string" ||
    value.recipient.postalAddress.trim().length === 0
  ) {
    return undefined;
  }
  return {
    op: "dispatch",
    shipmentId: value.shipmentId,
    nowMs: value.nowMs,
    recipient: {
      name: value.recipient.name,
      postalAddress: value.recipient.postalAddress,
    },
  };
}

function publicShipment(shipment: StoredShipment): PublicShipment {
  const fields = {
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
  };
  if (shipment.state === "queued") {
    return { ...fields, state: "queued" };
  }
  if (shipment.state === "dispatched") {
    return {
      ...fields,
      state: "dispatched",
      provider: shipment.provider,
      bookingId: shipment.bookingId,
      dispatchedAtMs: shipment.dispatchedAtMs,
    };
  }
  if (shipment.state === "deferred") {
    return {
      ...fields,
      state: "deferred",
      nextProvider: shipment.nextProvider,
      retryAtMs: shipment.retryAtMs,
      rejections: shipment.rejections.map(copyRejection),
    };
  }
  return {
    ...fields,
    state: "unavailable",
    rejections: shipment.rejections.map(copyRejection),
  };
}

function copyRejection(rejection: CarrierRejection): CarrierRejection {
  return {
    provider: rejection.provider,
    reason: rejection.reason,
  };
}

function isProvider(value: unknown): value is Provider {
  return value === "atlas" || value === "beacon";
}

function isRefusalReason(value: unknown): value is RefusalReason {
  return value === "unsupported_route" || value === "unsupported_parcel";
}

function parseRejections(value: unknown): CarrierRejection[] | undefined {
  if (!Array.isArray(value)) {
    return undefined;
  }
  const rejections = value.map((item) => {
    if (!isObject(item) || !isProvider(item.provider) || !isRefusalReason(item.reason)) {
      return undefined;
    }
    return { provider: item.provider, reason: item.reason };
  });
  if (rejections.some((item) => item === undefined)) {
    return undefined;
  }
  return rejections.filter((item): item is CarrierRejection => item !== undefined);
}

function parseStoredShipment(value: unknown): StoredShipment | undefined {
  if (
    !isObject(value) ||
    value.schemaVersion !== 1 ||
    typeof value.id !== "string" ||
    value.id.length === 0 ||
    typeof value.routeCode !== "string" ||
    value.routeCode.length === 0 ||
    typeof value.parcelGrams !== "number" ||
    !Number.isSafeInteger(value.parcelGrams) ||
    value.parcelGrams <= 0
  ) {
    return undefined;
  }
  const fields = {
    schemaVersion: 1,
    id: value.id,
    routeCode: value.routeCode,
    parcelGrams: value.parcelGrams,
  } as const;
  if (value.state === "queued") {
    return { ...fields, state: "queued" };
  }
  if (
    value.state === "dispatched" &&
    isProvider(value.provider) &&
    typeof value.bookingId === "string" &&
    value.bookingId.length > 0 &&
    typeof value.dispatchedAtMs === "number" &&
    Number.isSafeInteger(value.dispatchedAtMs) &&
    value.dispatchedAtMs >= 0
  ) {
    return {
      ...fields,
      state: "dispatched",
      provider: value.provider,
      bookingId: value.bookingId,
      dispatchedAtMs: value.dispatchedAtMs,
    };
  }
  if (
    value.state === "deferred" &&
    isProvider(value.nextProvider) &&
    typeof value.retryAtMs === "number" &&
    Number.isSafeInteger(value.retryAtMs)
  ) {
    const rejections = parseRejections(value.rejections);
    if (rejections !== undefined) {
      return {
        ...fields,
        state: "deferred",
        nextProvider: value.nextProvider,
        retryAtMs: value.retryAtMs,
        rejections,
      };
    }
  }
  if (value.state === "unavailable") {
    const rejections = parseRejections(value.rejections);
    if (rejections !== undefined) {
      return {
        ...fields,
        state: "unavailable",
        rejections,
      };
    }
  }
  return undefined;
}

function abortBody(
  shipmentId: string,
  failedAt: Provider | "repository",
  classification: AbortClassification,
  rejections: readonly CarrierRejection[],
): AbortBody {
  return {
    code: "dispatch_aborted",
    shipmentId,
    failedAt,
    classification,
    rejections: rejections.map(copyRejection),
  };
}

function providerRequest(shipment: StoredShipment, recipient: Recipient): ProviderRequest {
  return {
    shipmentId: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
    recipient: {
      name: recipient.name,
      postalAddress: recipient.postalAddress,
    },
    idempotencyKey: shipment.id,
  };
}

async function attemptCarrier(
  dependencies: ShippingDependencies,
  provider: Provider,
  shipment: StoredShipment,
  recipient: Recipient,
  nowMs: number,
): Promise<CarrierResult> {
  try {
    const request = providerRequest(shipment, recipient);
    const confirmation =
      provider === "atlas"
        ? await dependencies.atlas.book(request)
        : await dependencies.beacon.reserve(request);
    return parseConfirmation(provider, confirmation);
  } catch (error: unknown) {
    return parseCarrierRejection(provider, error, nowMs);
  }
}

function parseConfirmation(provider: Provider, confirmation: unknown): CarrierResult {
  if (!isObject(confirmation)) {
    return { kind: "aborted", failedAt: provider, classification: "invalid_provider_response" };
  }
  if (provider === "atlas") {
    if (typeof confirmation.bookingId === "string" && confirmation.bookingId.length > 0) {
      return { kind: "confirmed", provider, bookingId: confirmation.bookingId };
    }
    return { kind: "aborted", failedAt: provider, classification: "invalid_provider_response" };
  }
  if (typeof confirmation.reference === "string" && confirmation.reference.length > 0) {
    return { kind: "confirmed", provider, bookingId: confirmation.reference };
  }
  return { kind: "aborted", failedAt: provider, classification: "invalid_provider_response" };
}

function parseCarrierRejection(
  provider: Provider,
  error: unknown,
  nowMs: number,
): CarrierResult {
  if (!isObject(error)) {
    return { kind: "aborted", failedAt: provider, classification: "unknown_failure" };
  }
  if (provider === "atlas") {
    if (error.code === "cannot_ship") {
      if (isRefusalReason(error.reason)) {
        return { kind: "refused", rejection: { provider, reason: error.reason } };
      }
      return { kind: "aborted", failedAt: provider, classification: "invalid_provider_response" };
    }
    if (error.code === "rate_limited") {
      if (
        typeof error.retryAtMs === "number" &&
        Number.isSafeInteger(error.retryAtMs) &&
        error.retryAtMs > nowMs
      ) {
        return { kind: "throttled", provider, retryAtMs: error.retryAtMs };
      }
      return { kind: "aborted", failedAt: provider, classification: "invalid_provider_response" };
    }
    return { kind: "aborted", failedAt: provider, classification: "unknown_failure" };
  }
  if (error.type === "rejected") {
    if (isObject(error.details) && isRefusalReason(error.details.reason)) {
      return { kind: "refused", rejection: { provider, reason: error.details.reason } };
    }
    return { kind: "aborted", failedAt: provider, classification: "invalid_provider_response" };
  }
  if (error.type === "throttled") {
    if (
      isObject(error.details) &&
      typeof error.details.retryAtMs === "number" &&
      Number.isSafeInteger(error.details.retryAtMs) &&
      error.details.retryAtMs > nowMs
    ) {
      return { kind: "throttled", provider, retryAtMs: error.details.retryAtMs };
    }
    return { kind: "aborted", failedAt: provider, classification: "invalid_provider_response" };
  }
  return { kind: "aborted", failedAt: provider, classification: "unknown_failure" };
}

function dispatchStatus(shipment: StoredShipment): number {
  if (shipment.state === "deferred") {
    return 202;
  }
  if (shipment.state === "unavailable") {
    return 422;
  }
  return 200;
}

async function persistDecision(
  dependencies: ShippingDependencies,
  shipment: StoredShipment,
  abortRejections: readonly CarrierRejection[],
): Promise<ServiceResponse | undefined> {
  try {
    await dependencies.repository.save(shipment.id, shipment);
  } catch {
    const body = abortBody(shipment.id, "repository", "repository_failure", abortRejections);
    dependencies.logger.info({
      shipmentId: shipment.id,
      action: "aborted",
      failedAt: "repository",
      classification: "repository_failure",
      rejections: body.rejections,
    });
    return { status: 500, body };
  }
  emitDecisionEvent(dependencies, shipment);
  return undefined;
}

function emitDecisionEvent(dependencies: ShippingDependencies, shipment: StoredShipment): void {
  if (shipment.state === "dispatched") {
    dependencies.logger.info({
      shipmentId: shipment.id,
      action: "dispatched",
      provider: shipment.provider,
    });
  }
  if (shipment.state === "deferred") {
    dependencies.logger.info({
      shipmentId: shipment.id,
      action: "deferred",
      provider: shipment.nextProvider,
      retryAtMs: shipment.retryAtMs,
      rejections: shipment.rejections.map(copyRejection),
    });
  }
  if (shipment.state === "unavailable") {
    dependencies.logger.info({
      shipmentId: shipment.id,
      action: "unavailable",
      rejections: shipment.rejections.map(copyRejection),
    });
  }
}

function emitAbort(
  dependencies: ShippingDependencies,
  shipmentId: string,
  failedAt: Provider | "repository",
  classification: AbortClassification,
  rejections: readonly CarrierRejection[],
): ServiceResponse {
  const body = abortBody(shipmentId, failedAt, classification, rejections);
  dependencies.logger.info({
    shipmentId,
    action: "aborted",
    failedAt,
    classification,
    rejections: body.rejections,
  });
  return { status: 500, body };
}

async function finishDecision(
  dependencies: ShippingDependencies,
  shipment: StoredShipment,
  abortRejections: readonly CarrierRejection[],
): Promise<ServiceResponse> {
  const failedSave = await persistDecision(dependencies, shipment, abortRejections);
  if (failedSave !== undefined) {
    return failedSave;
  }
  return {
    status: dispatchStatus(shipment),
    body: publicShipment(shipment),
  };
}

async function dispatchFromProvider(
  dependencies: ShippingDependencies,
  shipment: StoredShipment,
  provider: Provider,
  recipient: Recipient,
  nowMs: number,
  rejections: readonly CarrierRejection[],
): Promise<ServiceResponse> {
  const result = await attemptCarrier(dependencies, provider, shipment, recipient, nowMs);
  if (result.kind === "confirmed") {
    return finishDecision(dependencies, {
      schemaVersion: 1,
      id: shipment.id,
      routeCode: shipment.routeCode,
      parcelGrams: shipment.parcelGrams,
      state: "dispatched",
      provider: result.provider,
      bookingId: result.bookingId,
      dispatchedAtMs: nowMs,
    }, rejections);
  }
  if (result.kind === "throttled") {
    const deferredRejections = rejections.map(copyRejection);
    return finishDecision(dependencies, {
      schemaVersion: 1,
      id: shipment.id,
      routeCode: shipment.routeCode,
      parcelGrams: shipment.parcelGrams,
      state: "deferred",
      nextProvider: result.provider,
      retryAtMs: result.retryAtMs,
      rejections: deferredRejections,
    }, deferredRejections);
  }
  if (result.kind === "aborted") {
    return emitAbort(
      dependencies,
      shipment.id,
      result.failedAt,
      result.classification,
      rejections,
    );
  }
  const nextRejections = [...rejections.map(copyRejection), result.rejection];
  if (provider === "atlas") {
    return dispatchFromProvider(
      dependencies,
      shipment,
      "beacon",
      recipient,
      nowMs,
      nextRejections,
    );
  }
  return finishDecision(dependencies, {
    schemaVersion: 1,
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
    state: "unavailable",
    rejections: nextRejections,
  }, nextRejections);
}

export function createShippingService(dependencies: ShippingDependencies) {
  async function handle(input: unknown): Promise<ServiceResponse> {
    const command = parseCommand(input);
    if (!command) {
      return { status: 400, body: { code: "invalid_command" } };
    }

    let value: unknown;
    try {
      value = await dependencies.repository.get(command.shipmentId);
    } catch {
      return emitAbort(
        dependencies,
        command.shipmentId,
        "repository",
        "repository_failure",
        [],
      );
    }
    if (value === undefined) {
      return { status: 404, body: { code: "not_found" } };
    }

    const shipment = parseStoredShipment(value);
    if (shipment === undefined) {
      return emitAbort(
        dependencies,
        command.shipmentId,
        "repository",
        "repository_failure",
        [],
      );
    }
    if (command.op === "get") {
      return { status: 200, body: publicShipment(shipment) };
    }

    if (shipment.state === "dispatched" || shipment.state === "unavailable") {
      return {
        status: dispatchStatus(shipment),
        body: publicShipment(shipment),
      };
    }

    if (shipment.state === "deferred") {
      if (command.nowMs < shipment.retryAtMs) {
        return { status: 202, body: publicShipment(shipment) };
      }
      return dispatchFromProvider(
        dependencies,
        shipment,
        shipment.nextProvider,
        command.recipient,
        command.nowMs,
        shipment.rejections,
      );
    }

    return dispatchFromProvider(
      dependencies,
      shipment,
      "atlas",
      command.recipient,
      command.nowMs,
      [],
    );
  }

  return { handle };
}
